.about-page {
  --about-radius: 16px;
  --about-border: rgba(0, 0, 0, 0.06);
  --about-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}
.about-page .hero-section {
  text-align: center;
  padding: 60px 20px 80px;
  background: linear-gradient(to bottom, rgba(8, 163, 255, 0.05), transparent);
  border-radius: var(--about-radius);
  margin-bottom: 30px;
}
.about-page .hero-title {
  font-size: clamp(36px, 6vw, 64px);
  font-weight: 900;
  margin: 0 0 16px;
  color: var(--primary, #08a3ff);
}
.about-page .hero-subtitle {
  font-size: clamp(18px, 2.5vw, 28px);
  font-weight: 700;
  margin: 0 0 12px;
}
.about-page .hero-desc {
  font-size: clamp(16px, 1.8vw, 20px);
  color: #555;
  max-width: 720px;
  margin: 0 auto 24px;
  line-height: 1.6;
}
.about-page .cta-buttons {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 20px;
}
.about-page .cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 600;
  transition: all 0.2s ease;
}
.about-page .cta-btn--primary {
  background: linear-gradient(135deg, #08a3ff, #0e8dff);
  color: #fff;
  border: none;
}
.about-page .cta-btn--secondary {
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
  color: var(--font-color, #222);
  border: 1px solid var(--about-border);
}
.about-page .cta-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
}
.about-page .section {
  margin: 40px 0;
  padding: 30px 0;
}
.about-page .section-title {
  text-align: center;
  margin-bottom: 30px;
}
.about-page .section-label {
  font-size: 14px;
  color: var(--primary, #08a3ff);
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 8px;
}
.about-page .section-heading {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 900;
  margin: 0;
}
.about-page .section-desc {
  text-align: center;
  color: #777;
  max-width: 640px;
  margin: 12px auto 0;
  font-size: 17px;
  line-height: 1.6;
}
.about-page .process-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 18px;
  margin-top: 30px;
}
.about-page .process-card {
  padding: 22px 18px;
  border-radius: var(--about-radius);
  border: 1px solid var(--about-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
  box-shadow: var(--about-shadow);
  transition: transform 0.2s ease;
}
.about-page .process-card:hover {
  transform: translateY(-3px);
}
.about-page .card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}
.about-page .card-icon {
  width: 42px;
  height: 42px;
  border-radius: 999px;
  border: 2px solid var(--primary, #08a3ff);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary, #08a3ff);
}
.about-page .card-step {
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid #b8e3ff;
  color: #0ea5ff;
  font-size: 12px;
  font-weight: 700;
}
.about-page .card-title {
  font-size: 22px;
  font-weight: 800;
  margin: 0 0 8px;
}
.about-page .card-lead {
  color: var(--primary, #08a3ff);
  font-weight: 600;
  margin: 0 0 10px;
}
.about-page .card-list {
  margin: 0;
  padding-left: 0;
  list-style: none;
}
.about-page .card-list li {
  position: relative;
  padding-left: 16px;
  margin: 8px 0;
  color: #666;
  line-height: 1.5;
}
.about-page .card-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5em;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: #7fd3ff;
}
.about-page .testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 18px;
  margin-top: 30px;
}
.about-page .testimonial-card {
  padding: 22px 18px;
  border-radius: var(--about-radius);
  border: 1px solid var(--about-border);
  background: var(--card-bg, rgba(255, 255, 255, 0.85));
  min-height: 200px;
  display: flex;
  flex-direction: column;
}
.about-page .quote-icon {
  color: #7fd3ff;
  margin-bottom: 10px;
  font-size: 28px;
}
.about-page .testimonial-text {
  flex: 1;
  font-size: 17px;
  line-height: 1.65;
  color: #333;
  font-style: italic;
}
.about-page .testimonial-author {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid #eef4fb;
  font-weight: 700;
  font-size: 18px;
}
.about-page .founder-section {
  margin-top: 50px;
  padding: 40px 0;
}
.about-page .founder-grid {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 32px;
  align-items: center;
}
.about-page .founder-avatar {
  width: 180px;
  height: 180px;
  border-radius: 999px;
  overflow: hidden;
  border: 4px solid #e6f5ff;
  box-shadow: 0 10px 30px rgba(8, 163, 255, 0.15);
  margin: 0 auto;
}
.about-page .founder-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.about-page .founder-content h3 {
  font-size: 36px;
  font-weight: 900;
  margin: 0 0 12px;
}
.about-page .founder-content p {
  color: #666;
  font-size: 17px;
  line-height: 1.6;
  margin: 8px 0;
}
@media (max-width: 768px) {
  .about-page .founder-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .about-page .founder-avatar {
    margin-bottom: 20px;
  }
}



